// Everything the document needs is computed here, so the render node stays a layout.
const cfg = $('Set your document branding').first().json;
const req = cfg.request || {};

const md = String(req.markdown || '');
const title = String(req.title || 'Untitled document').trim();
const author = String(req.author || cfg.brandName || '').trim();

// 1. Walk the Markdown once: number the headings and collect them for the contents.
//    Fenced code blocks are skipped so a "# comment" inside one is not mistaken
//    for a heading.
const out = [];
const headings = [];
let inFence = false;
let h2 = 0;
let h3 = 0;

for (const line of md.split(/\r?\n/)) {
  if (/^\s*(```|~~~)/.test(line)) {
    inFence = !inFence;
    out.push(line);
    continue;
  }
  const m = inFence ? null : /^(#{2,3})\s+(.+?)\s*#*\s*$/.exec(line);
  if (!m) {
    out.push(line);
    continue;
  }
  const text = m[2].trim();
  let number;
  if (m[1].length === 2) {
    h2 += 1;
    h3 = 0;
    number = `${h2}.`;
  } else {
    if (h2 === 0) h2 = 1;
    h3 += 1;
    number = `${h2}.${h3}`;
  }
  headings.push({ level: m[1].length, number, text });
  out.push(`${m[1]} ${number} ${text}`);
}

const body = out.join('\n');
const words = body.split(/\s+/).filter(Boolean).length;
const minutes = Math.max(1, Math.round(words / 200));

// 2. The contents page, built from the headings that were just numbered, so the
//    two can never drift apart. Skipped for a document with nothing to list.
const wantsToc = cfg.addTableOfContents === true || cfg.addTableOfContents === 'true';
const toc = wantsToc && headings.length > 1
  ? ['## Contents', '']
      .concat(headings.map((h) => `${h.level === 2 ? '' : '   '}- ${h.number} ${h.text}`))
      .concat(['', '---', ''])
      .join('\n')
  : '';

// 3. A cover block with the facts a reader wants before reading.
const today = new Date().toISOString().slice(0, 10);
const sections = `${headings.length} section${headings.length === 1 ? '' : 's'}`;
const cover = [
  `# ${title}`,
  '',
  [author, today].filter(Boolean).join(' · '),
  '',
  `${words} words · about ${minutes} minute${minutes === 1 ? '' : 's'} to read · ${sections}`,
  '',
  '---',
  '',
].join('\n');

// 4. Header, page footer and accent colour, all derived from the one config node.
const escapeHtml = (s) => String(s).replace(/[&<>"]/g, (c) => (
  { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]
));
const accent = /^#[0-9a-fA-F]{3,8}$/.test(String(cfg.accentColour || ''))
  ? String(cfg.accentColour)
  : '#123a5f';

const headerHtml = `<div style="width:100%;display:flex;justify-content:space-between;color:#8a94a6;">`
  + `<span>${escapeHtml(cfg.brandName || '')}</span><span>${escapeHtml(title)}</span></div>`;

const css = `
  body { color: #1c2430; }
  h1 { color: ${accent}; border-bottom: 2px solid ${accent}; padding-bottom: 6px; }
  h2 { color: ${accent}; margin-top: 22px; }
  h3 { color: #35415a; }
  table { border-collapse: collapse; width: 100%; }
  th, td { border: 1px solid #d4dae5; padding: 6px 9px; }
  th { background: ${accent}; color: #ffffff; text-align: left; }
  tr { break-inside: avoid; }
  blockquote { border-left: 3px solid ${accent}; color: #4a5568; margin-left: 0; padding-left: 12px; }
  code { background: #f2f5fa; padding: 1px 4px; border-radius: 3px; }
`;

const slug = title.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 60);

return [{
  json: {
    markdown: cover + toc + body,
    fileName: `${slug || 'document'}.pdf`,
    documentTitle: title,
    author,
    headerHtml,
    css,
    words,
    minutes,
    headings: headings.length,
  },
}];
